from playwright.sync_api import sync_playwright
import json,pathlib,re,os
root=pathlib.Path(os.environ.get('PROJECT_CONSTELLATION_ROOT','/mnt/data/project-constellation'));html=(root/'popup.html').read_text();html=re.sub(r'<link[^>]+popup\.css[^>]*>','',html);html=re.sub(r'<script[^>]+popup\.js[^>]*></script>','',html);css=(root/'popup.css').read_text();js=(root/'popup.js').read_text()
mock=r'''window.__created=[];window.chrome={runtime:{id:'pc-test',getURL:(p)=>'chrome-extension://pc-test/'+p},storage:{local:{get:async()=>({projectConstellationPerformanceSettings:{enabled:true,responsiveScrolling:true,adaptiveMotionRelief:false}}),set:async(v)=>{window.__lastStored=v;}}},tabs:{query:async()=>[{id:7,windowId:1,url:'https://chatgpt.com/c/test'}],sendMessage:async(id,msg)=>({provider:{id:'chatgpt',name:'ChatGPT'},chat:{id:'chatgpt:test',status:'running'},metrics:{totalLongTasks:msg.type==='PC_RESET_METRICS'?0:4,maxLongTaskMs:110,route:'/c/test'},pressure:{pressure:'normal'},capabilities:{constellationCapture:true}}),create:async(o)=>{window.__created.push(o);return {id:8};}},sidePanel:{open:async()=>{throw new Error('side panel unavailable');}}};window.close=()=>{window.__closed=true;};'''
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':420,'height':720});errors=[];page.on('pageerror',lambda exc:errors.append(str(exc)));page.set_content(html,wait_until='load');page.evaluate(mock);page.add_style_tag(content=css);page.add_script_tag(content=js);page.wait_for_timeout(250)
    before=page.evaluate('''()=>({pressure:document.querySelector('#pressure').textContent,tasks:document.querySelector('#longTasks').textContent,provider:document.querySelector('#provider').textContent,state:document.querySelector('#chatState').textContent,enabled:document.querySelector('#enabled').checked})''');page.locator('#openHome').click();page.wait_for_timeout(20);page.locator('#openConstellation').click();page.wait_for_timeout(20);page.locator('#openAccounts').click();page.wait_for_timeout(20);created=page.evaluate('window.__created');page.locator('#resetMetrics').click();page.wait_for_timeout(50);after=page.locator('#longTasks').text_content();page.screenshot(path=os.environ.get('PROJECT_CONSTELLATION_POPUP_SCREENSHOT','/mnt/data/project-constellation/dist/popup-smoke.png'));print(json.dumps({'before':before,'created':created,'after':after,'errors':errors},sort_keys=True));assert before['pressure']=='normal' and before['tasks']=='4' and before['provider']=='ChatGPT' and before['state']=='running' and before['enabled'];assert any(x['url'].endswith('/home.html') for x in created);assert any(x['url'].endswith('/sidepanel.html') for x in created);assert any('home.html?view=connections' in x['url'] for x in created);assert after=='0';assert not errors;browser.close()
